#' Coefficient Stability (Oster)
#'
#' 
#' @param data .
#' @param outcome .
#' @param treat .
#' @param covs .
#' @param rmaxType .
#' @param rmax .
#' @param delta .
#' @param beta0 .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$est} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$res} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$grid} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$dPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$est$asDF}
#'
#' \code{as.data.frame(results$est)}
#'
#' @export
oster <- function(
    data,
    outcome,
    treat,
    covs,
    rmaxType = "multiple",
    rmax = 1.3,
    delta = 1,
    beta0 = 0,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("oster requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(covs), covs, NULL))


    options <- osterOptions$new(
        outcome = outcome,
        treat = treat,
        covs = covs,
        rmaxType = rmaxType,
        rmax = rmax,
        delta = delta,
        beta0 = beta0,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- osterClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

